css:
/* 丑萌 · 手作触感 Naive Craft
   纸面、蜡笔色、歪斜边框、波浪下划线、随手写的标签。刻意不做对齐与完美圆角，
   卡片轻微旋转，像贴在墙上的手账。纯 CSS。 */

html[data-theme] {
  color-scheme: light;
  --bg: #fbf6e9;
  --ink: #2d2a24; --muted: #6b6455; --dim: #948b78;
  --soft: #3f3a31; --meta: #6b6455; --bright: #1d1a15;
  --line: #ddd2ba; --line2: #eae2cf;
  --accent: #e4572e; --accent2: #3d7bd6; --accentText: #ffffff;
  --good: #4c9f70; --warn: #e0a132;
  --glow1: rgba(228, 87, 46, 0.14); --glow2: rgba(61, 123, 214, 0.12);
  --panel: #fffaf0; --panel2: #fff4dd;
  --dock1: #fffaf0; --dock2: #fff6e6;
  --glass: #fffaf0;
  --track: #efe6d2; --scroll: #d8c9ab; --coverbg: #f6edd9;
  --menu: #fffaf0; --menu1: #fffdf7; --menu2: #fff3da; --chev: #8d8371;
  --edge: #d8c9ab; --edge2: #e4572e;
  --hover: #fff0d2; --tick: #e0d4bb;
  --inset: rgba(255, 255, 255, 0.7); --wordactive: #1d1a15; --swborder: #c9bb9f;
  --shadow-dock: 6px 7px 0 rgba(45, 42, 36, 0.12);
  --serif: "Comic Sans MS", "Segoe Print", "Bradley Hand", "KaiTi", "STKaiti", cursive;
  --bottom: 140px;
  --shell-nav: #fff7e6; --shell-nav2: #fff7e6;
  --shell-navin: #2d2a24; --shell-navmuted: #6b6455; --shell-navline: #e2d6bd;
}

html[data-theme] body {
  background:
    radial-gradient(rgba(45, 42, 36, 0.05) 1px, transparent 1.4px) 0 0 / 16px 16px,
    linear-gradient(180deg, #fdf9ee, #f7f0df);
}
/* 铅笔颗粒 */
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.4;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='p'><feTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23p)' opacity='0.18'/></svg>");
  mix-blend-mode: multiply;
}

/* 侧栏：钉在左边的手账页 */
html[data-theme] .sidebar {
  margin: 12px 0 12px 12px; padding: 22px 14px;
  border: 2px solid #dccfb4; border-radius: 18px 10px 20px 12px / 12px 18px 10px 20px;
  background: #fffaf0;
  box-shadow: 4px 5px 0 rgba(45, 42, 36, 0.08), inset 0 1px 0 #fff;
  transform: rotate(-0.35deg);
}
html[data-theme] .brand { padding: 0 6px 18px; border-bottom: 2px dashed #ddd2ba; margin-bottom: 14px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong { font-family: var(--serif); font-weight: 700; letter-spacing: 0.02em; }
html[data-theme] .nav button {
  border: 2px solid transparent; border-radius: 14px 8px 16px 10px / 10px 14px 8px 16px;
  font-family: var(--serif); font-size: 12.5px; color: #5a5346;
}
html[data-theme] .nav button:hover { border-color: #ddd2ba; background: #fff3da; color: #2d2a24; }
html[data-theme] .nav button.active {
  border-color: #e4572e; background: #ffe9df; color: #2d2a24;
  box-shadow: 3px 3px 0 rgba(228, 87, 46, 0.22);
}

/* 顶栏：一条手画的线 */
html[data-theme] .topbar {
  margin-top: 12px; padding: 0 16px; height: 64px; border: 0; border-radius: 14px;
  background: #fffaf0;
  box-shadow: 4px 5px 0 rgba(45, 42, 36, 0.07);
}
html[data-theme] .search-global { border: 2px dashed #ddd2ba; border-radius: 12px; background: #fffdf7; }
html[data-theme] .icon-btn { border: 2px solid #ddd2ba; border-radius: 50% 46% 52% 48%; background: #fffdf7; }

/* 首页：便签式主视觉 */
html[data-theme] .ledger-mast {
  margin-top: 20px; padding: 30px 32px;
  border: 2px solid #e6d9bd; border-radius: 22px 12px 24px 14px / 14px 22px 12px 24px;
  background:
    repeating-linear-gradient(180deg, transparent 0 30px, rgba(45, 42, 36, 0.055) 30px 31px),
    #fffaf0;
  box-shadow: 6px 7px 0 rgba(45, 42, 36, 0.09);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(38px, 5.2vw, 70px); line-height: 1.02;
  letter-spacing: -0.5px; color: #2d2a24;
}
html[data-theme] .ledger-mast h1 em { color: #e4572e; font-style: normal; text-decoration: underline wavy #3d7bd6 2px; text-underline-offset: 6px; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #6b6455; }

/* 卡片：贴纸，轻微歪 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 2px solid #e6d9bd; border-radius: 18px 10px 20px 12px / 12px 18px 10px 20px;
  background: #fffaf0; box-shadow: 4px 5px 0 rgba(45, 42, 36, 0.08);
}
html[data-theme] .pod-card:nth-child(odd) { transform: rotate(0.25deg); }
html[data-theme] .pod-card:nth-child(even) { transform: rotate(-0.3deg); }
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  transform: rotate(0deg) translateY(-2px); box-shadow: 6px 8px 0 rgba(45, 42, 36, 0.12);
}
html[data-theme] .btn {
  border: 2px solid #2d2a24; border-radius: 12px 8px 14px 9px / 9px 12px 8px 14px;
  background: #fff3da; color: #2d2a24; font-family: var(--serif); font-weight: 700;
  box-shadow: 3px 3px 0 rgba(45, 42, 36, 0.16);
}
html[data-theme] .btn.primary { background: #ffd8c9; border-color: #e4572e; }
html[data-theme] .btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 rgba(45, 42, 36, 0.16); }

/* 统计：三张便签 */
html[data-theme] #page-stats .page-head {
  margin: 16px 0; padding: 26px 28px; border: 2px solid #e6d9bd;
  border-radius: 22px 12px 24px 14px / 14px 22px 12px 24px;
  background: #fff4dd; box-shadow: 5px 6px 0 rgba(45, 42, 36, 0.08);
}
html[data-theme] #page-stats .page-head h1 { font-family: var(--serif); font-size: clamp(30px, 4.2vw, 50px); color: #2d2a24; }
html[data-theme] #page-stats .eyebrow { color: #e4572e; letter-spacing: 0.2em; }
html[data-theme] #page-stats .stat {
  border: 2px solid #e6d9bd; border-radius: 14px 8px 16px 10px / 10px 14px 8px 16px;
  background: #fffaf0; box-shadow: 4px 5px 0 rgba(45, 42, 36, 0.08);
}
html[data-theme] #statsCards .stat:nth-child(1) { background: #ffe9df; }
html[data-theme] #statsCards .stat:nth-child(2) { background: #e7f0ff; }
html[data-theme] #statsCards .stat:nth-child(3) { background: #fff0c9; }
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat strong { font-family: var(--serif); font-size: 36px; color: #2d2a24; background: none; -webkit-text-fill-color: #2d2a24; }
html[data-theme] #page-stats .stat label, html[data-theme] #page-stats .stat em { color: #6b6455; }
html[data-theme] #page-stats .card { border-radius: 20px 12px 18px 10px / 10px 20px 12px 18px; }
html[data-theme] #page-stats .stat-bar { border-radius: 10px; background: #fff4dd; border-bottom: 1px dashed #ddd2ba; }
html[data-theme] #page-stats .stat-track { height: 8px; border-radius: 8px; background: #efe6d2; box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 8px; background: repeating-linear-gradient(90deg, #e4572e 0 6px, #f0805f 6px 12px); box-shadow: none; }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 26px; padding: 26px 28px; border: 2px solid #e6d9bd;
  border-radius: 22px 12px 24px 14px / 14px 22px 12px 24px;
  background: #eef3ff; box-shadow: 5px 6px 0 rgba(45, 42, 36, 0.08);
}
html[data-theme] #page-stats .year-title { font-family: var(--serif); font-size: 42px; color: #2d2a24; background: none; -webkit-text-fill-color: #2d2a24; }
html[data-theme] #page-stats #echoYear { border: 2px solid #2d2a24; border-radius: 10px; background: #fffaf0; color: #2d2a24; font-family: var(--serif); }

/* 设置 */
html[data-theme] .ct-box { border: 2px solid #e6d9bd; border-radius: 16px 10px 18px 12px; background: #fffaf0; }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 2px dashed #ddd2ba; border-radius: 10px; background: #fffdf7; color: #2d2a24;
}

/* 播放舱：一张折角贴纸 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 2px solid #e6d9bd;
    border-radius: 20px 12px 22px 14px / 14px 20px 12px 22px;
    background: #fffaf0; box-shadow: 6px 7px 0 rgba(45, 42, 36, 0.1);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border: 2px solid #2d2a24; border-radius: 50% 46% 52% 48%; background: #ffd8c9; color: #2d2a24; box-shadow: 2px 2px 0 rgba(45, 42, 36, 0.16); }
html[data-theme] .mini-player { border: 2px solid #e6d9bd; border-radius: 14px; background: #fffaf0; box-shadow: 4px 5px 0 rgba(45, 42, 36, 0.1); }

html[data-theme] .cue.active .word { color: #2d2a24; background: #ffe0d2; border-radius: 4px; box-shadow: 0 2px 0 #e4572e; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #d8c9ab; border-radius: 6px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: #fbf6e9; color: #2d2a24; }
html[data-theme] .wp-bg { filter: blur(26px) saturate(120%) brightness(1.35) contrast(.96); opacity: .26; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(251,246,233,.95) 0%, rgba(251,246,233,.86) 50%, rgba(255,244,221,.78) 78%, rgba(251,246,233,.95) 100%); }
html[data-theme] .wp-kicker { color: #e4572e; font-weight:700;letter-spacing:.12em;text-transform:uppercase;text-decoration:underline wavy rgba(228,87,46,.5) 2px; }
html[data-theme] .wp-title { color: #2d2a24; font-weight:700;letter-spacing:-.01em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(45,42,36,.72); }
html[data-theme] .wp-cue.active::before { background: #e4572e; box-shadow: none; width:clamp(4px,.3vw,6px);border-radius:2px;transform:rotate(-1.4deg); }
html[data-theme] .wp-cue.active .wp-en { color: #2d2a24; text-shadow: 0 2px 0 rgba(228,87,46,.22); font-weight:700; }
html[data-theme] .wp-word.past { color: #2d2a24; }
html[data-theme] .wp-word.active { color: #b8421f; background-image: none; text-shadow: none; text-decoration:underline wavy rgba(228,87,46,.65) 2px;text-underline-offset:4px;border-radius:0; }
html[data-theme] .wp-zh { color: rgba(45,42,36,.62); font-weight:400; }
html[data-theme] .wp-label { color: rgba(45,42,36,.42); }
html[data-theme] .wpbtn { background: #fffaf0; border-color: #ddd2ba; color: #2d2a24; border-radius:12px;border-width:2px;border-style:dashed;transform:rotate(-.6deg);font-weight:600; }
html[data-theme] .wpbtn:hover { background: #ffe6c8; border-color: #e4572e; color: #2d2a24; }
html[data-theme] .wp-shade::after { background-image: radial-gradient(rgba(45,42,36,.07) .7px, transparent .7px); background-size: 4px 4px; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
